import React, { useEffect, useRef, useState} from "react";
import "codemirror/mode/javascript/javascript";
import "codemirror/theme/dracula.css";
import "codemirror/addon/edit/closetag";
import "codemirror/addon/edit/closebrackets";
import "codemirror/lib/codemirror.css";
import CodeMirror from "codemirror";


 function Editor({socketRef,roomId}) {
    const editorRef = useRef(null);
    const [output, setOutput] = useState("");
  const [isRunning, setIsRunning] = useState(false);
  useEffect(() => {
    const init = async () => {
      const editor = CodeMirror.fromTextArea(
       document.getElementById("realtimeEditor"),
        {
          mode: { name: "javascript", json: true },
          theme: "dracula",
          autoCloseTags: true,
          autoCloseBrackets: true,
          lineNumbers: true,
        }
      );
      editorRef.current = editor;
      editor.setSize(null, "400px");
      editorRef.current.on("change", (instance, changes) => {
         // console.log("changes", instance ,  changes );
         const { origin } = changes;
         const code = instance.getValue(); // code has value which we write
         if (origin !== "setValue") {
          socketRef.current.emit(
            "code-change", {
              roomId,
              code,
            }
          );
         }
      });

      
    };
    init();
},[]);
 
useEffect(() => {
  if (socketRef.current) {
    socketRef.current.on("code-change", ({ code }) => {
      if (code !== null) {
        editorRef.current.setValue(code);
      }
    });
    //experiment 
      socketRef.current.on("output-change", ({ output }) => {
      setOutput(output);
    });
  }
  return () => {
    socketRef.current.off("code-change");
    socketRef.current.off("output-change");
  };
},[socketRef.current]
);

//experiment

const executeCode = () => {
  setIsRunning(true);
  const code = editorRef.current.getValue();
  
  try {
    // Create a secure context for evaluation
    const secureEval = (code) => {
      try {
        // Redirect console.log to our output
        const originalConsole = window.console.log;
        let output = '';
        window.console.log = (...args) => {
          output += args.map(arg => 
            typeof arg === 'object' ? JSON.stringify(arg, null, 2) : String(arg)
          ).join(' ') + '\n';
        };

        // Execute the code
        eval(code);

        // Restore original console.log
        window.console.log = originalConsole;
        return output;
      } catch (error) {
        return `Error: ${error.message}`;
      }
    };

    const result = secureEval(code);
    
    // Emit the output to all users
    socketRef.current.emit("output-change", {
      roomId,
      output: result,
    });
    
    setOutput(result);
  } catch (error) {
    const errorMessage = `Error: ${error.message}`;
    socketRef.current.emit("output-change", {
      roomId,
      output: errorMessage,
    });
    setOutput(errorMessage);
  }
  
  setIsRunning(false);
};



  return (
    <div style={{ height: "650px", display: "flex", flexDirection: "column" }}>
       <div className="flex-1">
      <textarea id="realtimeEditor"></textarea>
      </div>
      <div className="h-48 bg-gray-900 text-white p-4 font-mono relative">
        <div className="flex justify-between items-center mb-2">
          <span className="text-gray-400">Terminal Output</span>
          <button
            onClick={executeCode}
            disabled={isRunning}
            className={`px-4 py-1 rounded ${
              isRunning 
                ? 'bg-gray-600 cursor-not-allowed' 
                : 'bg-green-600 hover:bg-green-700'
            }`}
          >
            {isRunning ? 'Running...' : 'Run Code'}
          </button>
        </div>
        <div className="h-32 overflow-auto bg-black p-2 rounded">
          <pre className="text-green-400">
            {output || 'Click "Run Code" to see output...'}
          </pre>
        </div>
      </div>
    </div>
  );
}
export default Editor;
